create extension if not exists pgcrypto;
create table public.departments(id uuid primary key default gen_random_uuid(),code text not null unique check(code ~ '^[A-Z0-9-]{2,20}$'),name text not null,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null default 'staff' check(role in ('staff','admin')),active boolean not null default true,created_at timestamptz not null default now());
create table public.department_members(department_id uuid not null references public.departments(id),user_id uuid not null references public.profiles(id),primary key(department_id,user_id));
create table public.registry_counters(department_id uuid not null references public.departments(id),registry_year integer not null,latest integer not null default 0,primary key(department_id,registry_year));
create table public.memo_registrations(id uuid primary key default gen_random_uuid(),department_id uuid not null references public.departments(id),registry_year integer not null,running_number integer not null,registry_number text not null,subject text not null,recipient text not null,remark text not null default '',created_by uuid not null references public.profiles(id),issued_at timestamptz not null default now(),status text not null default 'issued' check(status in ('issued','cancelled')),cancelled_at timestamptz,cancelled_by uuid references public.profiles(id),cancellation_reason text,request_key uuid not null,unique(department_id,registry_year,running_number),unique(created_by,request_key));
create table public.attachments(id uuid primary key default gen_random_uuid(),memo_id uuid not null references public.memo_registrations(id),storage_path text not null unique,file_name text not null,uploaded_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.memo_audit_logs(id bigint generated always as identity primary key,memo_id uuid references public.memo_registrations(id),actor_id uuid references public.profiles(id),action text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index on public.memo_registrations(department_id,issued_at desc);
create index on public.memo_registrations(registry_number);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin' and active)$$;
create or replace function public.is_member(p_department uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.department_members m join public.profiles p on p.id=m.user_id where m.department_id=p_department and m.user_id=(select auth.uid()) and p.active) or public.is_admin()$$;
revoke all on function public.is_admin() from public,anon;revoke all on function public.is_member(uuid) from public,anon;
grant execute on function public.is_admin() to authenticated;grant execute on function public.is_member(uuid) to authenticated;
create or replace function public.issue_memo(p_department_id uuid,p_subject text,p_recipient text,p_remark text,p_request_key uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare v_user uuid:=auth.uid();v_year integer;v_next integer;v_code text;v_id uuid;begin
 if v_user is null or not public.is_member(p_department_id) then raise exception 'ไม่มีสิทธิ์ออกเลขในกลุ่มงานนี้';end if;
 if length(trim(p_subject)) not between 1 and 1000 or length(trim(p_recipient)) not between 1 and 300 or length(p_remark)>2000 then raise exception 'ข้อมูลไม่ถูกต้อง';end if;
 select id into v_id from public.memo_registrations where created_by=v_user and request_key=p_request_key;
 if v_id is not null then return v_id;end if;
 select code into v_code from public.departments where id=p_department_id;
 if v_code is null then raise exception 'ไม่พบกลุ่มงาน';end if;
 v_year:=extract(year from (now() at time zone 'Asia/Bangkok'))::integer+543;
 insert into public.registry_counters(department_id,registry_year,latest) values(p_department_id,v_year,0) on conflict do nothing;
 select latest into v_next from public.registry_counters where department_id=p_department_id and registry_year=v_year for update;
 select id into v_id from public.memo_registrations where created_by=v_user and request_key=p_request_key;
 if v_id is not null then return v_id;end if;
 v_next:=v_next+1;
 update public.registry_counters set latest=v_next where department_id=p_department_id and registry_year=v_year;
 insert into public.memo_registrations(department_id,registry_year,running_number,registry_number,subject,recipient,remark,created_by,request_key) values(p_department_id,v_year,v_next,v_code||'/'||lpad(v_next::text,4,'0')||'/'||v_year,trim(p_subject),trim(p_recipient),p_remark,v_user,p_request_key) returning id into v_id;
 insert into public.memo_audit_logs(memo_id,actor_id,action) values(v_id,v_user,'issued');return v_id;
end$$;
create or replace function public.cancel_memo(p_memo_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$
declare v_user uuid:=auth.uid();begin
 if v_user is null or not public.is_admin() then raise exception 'เฉพาะผู้ดูแลระบบ';end if;
 if length(trim(p_reason))<5 then raise exception 'กรุณาระบุเหตุผล';end if;
 update public.memo_registrations set status='cancelled',cancelled_at=now(),cancelled_by=v_user,cancellation_reason=trim(p_reason) where id=p_memo_id and status='issued';
 if not found then raise exception 'ไม่พบรายการที่ยกเลิกได้';end if;
 insert into public.memo_audit_logs(memo_id,actor_id,action,details) values(p_memo_id,v_user,'cancelled',jsonb_build_object('reason',p_reason));
end$$;
revoke all on function public.issue_memo(uuid,text,text,text,uuid) from public,anon;
revoke all on function public.cancel_memo(uuid,text) from public,anon;
grant execute on function public.issue_memo(uuid,text,text,text,uuid) to authenticated;
grant execute on function public.cancel_memo(uuid,text) to authenticated;
alter table public.departments enable row level security;
alter table public.profiles enable row level security;
alter table public.department_members enable row level security;
alter table public.registry_counters enable row level security;
alter table public.memo_registrations enable row level security;
alter table public.attachments enable row level security;
alter table public.memo_audit_logs enable row level security;
create policy departments_read on public.departments for select to authenticated using(public.is_member(id));
create policy departments_admin_insert on public.departments for insert to authenticated with check(public.is_admin());
create policy profiles_read on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_admin());
create policy members_read on public.department_members for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy memos_read on public.memo_registrations for select to authenticated using(public.is_member(department_id));
create policy attachments_read on public.attachments for select to authenticated using(exists(select 1 from public.memo_registrations m where m.id=memo_id and public.is_member(m.department_id)));
create policy attachments_insert on public.attachments for insert to authenticated with check(uploaded_by=(select auth.uid()) and exists(select 1 from public.memo_registrations m where m.id=memo_id and public.is_member(m.department_id) and m.status='issued'));
create policy memo_audit_read on public.memo_audit_logs for select to authenticated using(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('memo-files','memo-files',false,10485760,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do nothing;
create policy memo_file_read on storage.objects for select to authenticated using(bucket_id='memo-files' and exists(select 1 from public.attachments a join public.memo_registrations m on m.id=a.memo_id where a.storage_path=name and public.is_member(m.department_id)));
create policy memo_file_upload on storage.objects for insert to authenticated with check(bucket_id='memo-files' and exists(select 1 from public.memo_registrations m where m.id=split_part(name,'/',2)::uuid and m.department_id::text=split_part(name,'/',1) and m.status='issued' and public.is_member(m.department_id)));
